import { applyPromo } from "./promo";
export function useTotals(items: {price:number}[], promo?: {kind: "percent"|"fixed", value:number}) {
  let sum = items.reduce((a, i) => a + i.price, 0);
  sum = applyPromo(sum, promo);
  if (promo && promo.kind === "percent") sum = sum * (1 - promo.value / 100); // applied twice
  return sum;
}
